const crypto = require('crypto');
const http = require('http');

// Session store with CSRF protection
const sessions = new Map();
const CSRF_TOKEN_LENGTH = 32;
const SESSION_SECRET = crypto.randomBytes(64).toString('hex');

function generateSessionId() {
  return crypto.randomBytes(32).toString('hex');
}

function generateCsrfToken() {
  return crypto.randomBytes(CSRF_TOKEN_LENGTH).toString('hex');
}

function hashPassword(password, salt) {
  return crypto.pbkdf2Sync(password, salt, 310000, 32, 'sha256').toString('hex');
}

// User database (simulated)
const users = new Map();
users.set('admin', {
  passwordHash: hashPassword('supersecret', 'adminsalt'),
  salt: 'adminsalt',
  role: 'admin',
  failedAttempts: 0,
  lockedUntil: 0
});
users.set('user1', {
  passwordHash: hashPassword('password123', 'user1salt'),
  salt: 'user1salt',
  role: 'user',
  failedAttempts: 0,
  lockedUntil: 0
});

// Account lockout configuration
const MAX_FAILED_ATTEMPTS = 5;
const LOCKOUT_DURATION_MS = 15 * 60 * 1000;

function isAccountLocked(user) {
  if (user.lockedUntil > Date.now()) {
    return true;
  }
  if (user.lockedUntil !== 0 && user.lockedUntil <= Date.now()) {
    user.failedAttempts = 0;
    user.lockedUntil = 0;
  }
  return false;
}

function recordFailedAttempt(user) {
  user.failedAttempts += 1;
  if (user.failedAttempts >= MAX_FAILED_ATTEMPTS) {
    user.lockedUntil = Date.now() + LOCKOUT_DURATION_MS;
  }
}

// Permission matrix
const PERMISSIONS = {
  admin: ['read', 'write', 'delete', 'manage_users'],
  user: ['read', 'write'],
  guest: ['read']
};

function checkPermission(session, requiredPermission) {
  if (!session || !session.username) return false;
  const user = users.get(session.username);
  if (!user) return false;
  const perms = PERMISSIONS[user.role] || [];
  return perms.includes(requiredPermission);
}

// CSRF validation with double-submit pattern
function validateCsrf(session, requestCsrfToken) {
  if (!session || !session.csrfToken) return false;
  if (!requestCsrfToken) return false;

  const sessionToken = session.csrfToken;
  const requestToken = requestCsrfToken;

  // Length check before timing-safe comparison
  if (sessionToken.length !== requestToken.length) return false;

  return crypto.timingSafeEqual(
    Buffer.from(sessionToken, 'utf8'),
    Buffer.from(requestToken, 'utf8')
  );
}

// Resource access control
const resources = new Map();
resources.set('doc-1', { owner: 'admin', content: 'Secret admin document', accessLevel: 2 });
resources.set('doc-2', { owner: 'user1', content: 'User1 private notes', accessLevel: 1 });
resources.set('doc-3', { owner: 'admin', content: 'Public announcement', accessLevel: 0 });

// Access level hierarchy:
// 0 = public (anyone)
// 1 = authenticated users
// 2 = owner only

function canAccessResource(session, resource) {
  if (!resource) return false;

  const resourceLevel = resource.accessLevel;

  // Public resources - anyone can access
  if (resourceLevel == 0) return true;

  // Must be authenticated for level 1+
  if (!session || !session.username) return false;

  // Authenticated access
  if (resourceLevel == 1) return true;

  // Owner-only access (level 2)
  // Check if user is owner OR has admin role
  const user = users.get(session.username);
  if (!user) return false;

  if (resource.owner === session.username) return true;
  if (user.role === 'admin') return true;

  return false;
}

function parseBody(req) {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', chunk => {
      body += chunk;
      if (body.length > 1024 * 100) {
        reject(new Error('Body too large'));
      }
    });
    req.on('end', () => {
      try {
        resolve(JSON.parse(body));
      } catch (e) {
        reject(new Error('Invalid JSON'));
      }
    });
  });
}

function getSessionFromCookie(req) {
  const cookieHeader = req.headers.cookie || '';
  const cookies = cookieHeader.split(';').reduce((acc, c) => {
    const [key, val] = c.trim().split('=');
    if (key && val) acc[key] = val;
    return acc;
  }, {});
  const sessionId = cookies['session_id'];
  if (!sessionId) return null;
  return sessions.get(sessionId) || null;
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);

  try {
    // Login endpoint
    if (url.pathname === '/api/login' && req.method === 'POST') {
      const body = await parseBody(req);
      const { username, password } = body;

      if (!username || !password) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ error: 'Missing credentials' }));
      }

      const user = users.get(username);
      if (!user) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ error: 'Invalid credentials' }));
      }

      if (isAccountLocked(user)) {
        res.writeHead(423, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ error: 'Account locked' }));
      }

      const attemptHash = hashPassword(password, user.salt);
      const expectedHash = user.passwordHash;

      if (attemptHash.length !== expectedHash.length ||
          !crypto.timingSafeEqual(Buffer.from(attemptHash), Buffer.from(expectedHash))) {
        recordFailedAttempt(user);
        res.writeHead(401, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ error: 'Invalid credentials' }));
      }

      // Successful login
      user.failedAttempts = 0;
      const sessionId = generateSessionId();
      const csrfToken = generateCsrfToken();
      sessions.set(sessionId, { username, csrfToken, createdAt: Date.now() });

      res.writeHead(200, {
        'Content-Type': 'application/json',
        'Set-Cookie': `session_id=${sessionId}; HttpOnly; SameSite=Strict; Secure; Path=/`
      });
      return res.end(JSON.stringify({ csrfToken, role: user.role }));
    }

    // Get resource
    if (url.pathname.startsWith('/api/resource/') && req.method === 'GET') {
      const resourceId = url.pathname.slice('/api/resource/'.length);
      const resource = resources.get(resourceId);

      if (!resource) {
        res.writeHead(404, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ error: 'Not found' }));
      }

      const session = getSessionFromCookie(req);

      if (canAccessResource(session, resource)) {
        res.writeHead(200, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ id: resourceId, content: resource.content }));
      }

      res.writeHead(403, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify({ error: 'Access denied' }));
    }

    // Create resource (requires CSRF + write permission)
    if (url.pathname === '/api/resource' && req.method === 'POST') {
      const session = getSessionFromCookie(req);
      if (!session) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ error: 'Not authenticated' }));
      }

      const csrfToken = req.headers['x-csrf-token'];
      if (!validateCsrf(session, csrfToken)) {
        res.writeHead(403, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ error: 'CSRF validation failed' }));
      }

      if (!checkPermission(session, 'write')) {
        res.writeHead(403, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ error: 'Insufficient permissions' }));
      }

      const body = await parseBody(req);
      const { content, accessLevel } = body;

      if (!content || typeof content !== 'string') {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ error: 'Invalid content' }));
      }

      // Validate and normalize access level
      const level = parseInt(accessLevel, 10);
      const normalizedLevel = (level >= 0 && level <= 2) ? level : 1;

      const docId = `doc-${crypto.randomBytes(8).toString('hex')}`;
      resources.set(docId, {
        owner: session.username,
        content: content.slice(0, 10000),
        accessLevel: normalizedLevel
      });

      res.writeHead(201, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify({ id: docId }));
    }

    // Delete resource (requires CSRF + delete permission + ownership/admin)
    if (url.pathname.startsWith('/api/resource/') && req.method === 'DELETE') {
      const session = getSessionFromCookie(req);
      if (!session) {
        res.writeHead(401, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ error: 'Not authenticated' }));
      }

      const csrfToken = req.headers['x-csrf-token'];
      if (!validateCsrf(session, csrfToken)) {
        res.writeHead(403, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ error: 'CSRF validation failed' }));
      }

      if (!checkPermission(session, 'delete')) {
        res.writeHead(403, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ error: 'Insufficient permissions' }));
      }

      const resourceId = url.pathname.slice('/api/resource/'.length);
      const resource = resources.get(resourceId);

      if (!resource) {
        res.writeHead(404, { 'Content-Type': 'application/json' });
        return res.end(JSON.stringify({ error: 'Not found' }));
      }

      resources.delete(resourceId);
      res.writeHead(200, { 'Content-Type': 'application/json' });
      return res.end(JSON.stringify({ deleted: true }));
    }

    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));

  } catch (err) {
    res.writeHead(500, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Internal error' }));
  }
});

server.listen(3000);
module.exports = server;
